import base64,json
noise_pos = [0, 1, 2, 4, 5, 6, 7, 48, 49, 66, 149, 150, 284, 374, 375]
def decode(text):
    try:
        decoded = base64.b64decode(text).decode()
        decoded = json.loads(decoded)
        return decoded
    except Exception as e:
        decoded = base64.b64decode(fix_base64_padding(remove_noise(text))).decode("utf-8",errors="ignore")
        decoded = json.loads(decoded)
        return decoded
    
def fix_base64_padding(s):
    return s + '=' * (-len(s) % 4)
def remove_noise(text):
    return "".join([c for i, c in enumerate(text) if i not in noise_pos])

def find_noise_positions(samples):
    """（暂时废弃）找出多个样本中不同的字符位置，返回这些位置的索引列表"""
    min_len = min(len(s) for s in samples)
    noise_positions = []
    for i in range(min_len):
        byte_set = set(s[i] for s in samples)
        if len(byte_set) > 1:
            noise_positions.append(i)
    return noise_positions

